import { TreeDataNode } from '../types';
import { Value } from 'async-validator';
import { FlattenNode } from './interface';
import { omit } from 'lodash-es';

export function flattenTreeData<TreeDataType extends TreeDataNode = TreeDataNode>(
  treeNodeList: TreeDataType[],
  expandedKeys: Value[] | true,
): FlattenNode<TreeDataType>[] {
  const expandedKeySet = new Set(expandedKeys === true ? [] : expandedKeys);
  const flattenList: FlattenNode<TreeDataType>[] = [];

  function dig(list: TreeDataType[] | null, parent: FlattenNode<TreeDataType> | null = null) {
    return list?.map((treeNode, index) => {
      const pos = `${parent?.pos || '0'}-${index}`;
      const key = treeNode.value;

      // Add FlattenDataNode into list
      const flattenNode: FlattenNode<TreeDataType> = Object.assign(omit(treeNode, []), {
        key,
        parent,
        pos,
        children: null,
        data: treeNode,
      });
      flattenList.push(flattenNode);

      // Traverse children
      if (expandedKeys === true || expandedKeySet.has(key)) {
        flattenNode.children = dig((treeNode.children as TreeDataType[]) || null, flattenNode) || null;
      } else {
        flattenNode.children = null;
      }

      return flattenNode;
    });
  }
  dig(treeNodeList);
  return flattenList;
}
